inlineScript.scriptBlock:
// on change of (tenorDays, transitDays, baseDate, maturityDate, multi tenor matDates)
this.matDateController = function (caller) {
	const tenorDays = this.getFieldById("tenorDays");
	const transitDays = this.getFieldById("transitDays");
	const maturityDate = this.getFieldById("maturityDate");
	const baseDate = this.getFieldById("baseDate");
	const todayDate = this.context.options.todayDate?.get("value");

	const paymenTerms = this.context.options.paymentTerm?.get("value");
	const isMultiTenor = paymenTerms == "004" || false;
	const tenors = this.getViewByPath("/DC_Templete1/4/Table1")?.getData()?.items || [];
	const matDates = tenors.map((item) => item.instalmentMaturityDate);
	const today = getDateOnly(todayDate);

	// Initialize Base Date and Maturity Date
	const baseDateValue = baseDate.getData() ? getDateOnly(baseDate.getDate()) : null;
	const maturityDateValue = maturityDate.getData() ? getDateOnly(maturityDate.getDate()) : null;

	// Reset Validation
	baseDate.setValid(true);
	tenorDays.setValid(true);
	transitDays.setValid(true);
	maturityDate.setValid(true);

	// Validation Rules
	if (baseDateValue && baseDateValue > today) {
		baseDate.setValid(false, "Base Date must not exceed today's date.");
		return;
	}

	// if (maturityDateValue && baseDateValue && transitDays.getData() != null && baseDateValue > new Date(maturityDateValue?.getTime() - transitDays.getData() * 86400000)) {
	// 	baseDate.setValid(false, "Base Date must not exceed Maturity Date - Transit Days.");
	// 	return;
	// }

	 if (tenorDays.getData() < 0) {

		if (caller !== "tenorDays") tenorDays.setData(0);
		tenorDays.setValid(false, "Tenor Days must not be negative.");
		return;
	}

	if (transitDays.getData() < 0) {
		if (caller !== "transitDays") transitDays.setData(0);
		transitDays.setValid(false, "Transit Days must not be negative.");
		return;
	}
	// Multi-Tenor Logic
	if (isMultiTenor) {
		//			console.log("matDates: ", matDates);
		const latestMatDate = matDates.length > 0 && matDates[0] ? getLatestDate(matDates) : null;


		if (latestMatDate) {
			const tenor = Math.floor((latestMatDate?.getTime() - baseDateValue?.getTime()) / (1000 * 60 * 60 * 24)) || 0;
			console.log("tenor "+tenor);
			if (caller !== "tenorDays") tenorDays.setData(tenor);
			if (caller !== "transitDays") transitDays.setData(0);
			if (caller !== "maturityDate") maturityDate.setDate(latestMatDate);
			// alert(latestMatDate);

			if (baseDateValue && baseDateValue > latestMatDate) {
				baseDate.setValid(false, "Base Date must not exceed the latest Multi-Tenor Maturity Date.");
				return;
			}
		} else {
			// Handle the case where no valid matDates are available
			//				if (caller !== "maturityDate") maturityDate.setDate(today);

			if (caller !== "tenorDays") tenorDays.setData(0);
			if (caller !== "transitDays") transitDays.setData(0);
		}
	} else {
		// Non-Multi-Tenor Logic
		if (baseDateValue) {
			// Recalculate Maturity Date when Tenor Days or Transit Days change
			const newMaturityDate = new Date(baseDateValue);
			newMaturityDate.setDate(baseDateValue.getDate() + tenorDays.getData() + transitDays.getData());
			if (caller !== "maturityDate") maturityDate.setDate(newMaturityDate);
		}

		// Recalculate Tenor Days when Maturity Date changes
		const recalculatedTenor = Math.floor((maturityDateValue.getTime() - baseDateValue.getTime()) / (1000 * 60 * 60 * 24)) - transitDays.getData() || 0;

		if (caller == "maturityDate") tenorDays.setData(recalculatedTenor);
	}
};

this.setProdCodeVis = function () {
	var foView = bpmext.ui.getView("/DC_Templete1/4") || bpmext.ui.getView("/DC_Templete1/Financial_Details_FO_CV1");
	//	console.log("foView isAmend: ", foView);
	if (foView && foView?.isAmend) {
		foView.fieldsInit();
		foView.setBulkREADONLY(foView.listOfFields, false);
		//		me.setEnabled(false);
	}
};
this.getStageValue = function () {
	var stage = this.context.options.contractStage.get("value");
	this.context.binding.get("value").set("Stage", stage);
};

this.setNBECollectableAmount = function () {
	var collectableAmount = this.context.options.nbeCollectableAmount.get("value");
	//this.context.binding.get("value").set("amount", collectableAmount);
};

this.calculateMaturityDate = function () {
	this.runCalculateMaturityDate = function (parameter) {
		var baseDate = new Date(this.context.binding.get("value").get("baseDate"));
		var tenorDays = this.context.binding.get("value").get("tenorDays");
		var transitDays = this.context.binding.get("value").get("transitDays");

		if (!!this.context.options.paymentTerm.get("value")) {
			if (!!tenorDays && tenorDays < 0) this.ui.get("tenorDays").setValid(false, "Please enter a numeric number greater than  OR Equal zero");
			else if (!!transitDays && transitDays < 0) this.ui.get("transitDays").setValid(false, "Please enter a numeric number greater than  OR Equal zero");
			else {
				this.ui.get("transitDays").setValid(true);
				this.ui.get("tenorDays").setValid(true);
				if (this.context.options.paymentTerm.get("value") != "004") {
					// this.ui.get("maturityDate").setEnabled(true);

					function addDaysToDate(date, days) {
						var result = new Date(date);
						// Clone the date
						result.setDate(result.getDate() + days);
						return result;
					}
					var maturityDate = addDaysToDate(baseDate, tenorDays + transitDays);
					var validateDate = addDaysToDate(baseDate, 0);

					if (maturityDate < addDaysToDate(validateDate, transitDays)) {
						this.ui.get("maturityDate").setValid(false, "Maturity Date Must be >= Base date plus tranist days");
					} else {
						this.ui.get("maturityDate").setValid(true);
						this.context.binding.get("value").set("maturityDate", maturityDate);
					}
				} else {
					// this.ui.get("maturityDate").setEnabled(false);
				}
			}
		}
	}.bind(this);
	document.addEventListener("changeMaturity", (event) => {
		var parameter = event.detail;
		this.runCalculateMaturityDate(parameter);
	});
	document.addEventListener("input", (event) => {
		var parameter = event.detail;
		this.runCalculateMaturityDate(parameter);
	});
};

this.calculateTenorTransitDays = function () {
	this.runCalculateTenorTransitDays = function (parameter) {
		var baseDate = new Date(this.context.binding.get("value").get("baseDate"));
		var maturityDate = new Date(this.context.binding.get("value").get("maturityDate"));
		var transitDays = this.context.binding.get("value").get("transitDays");
		var tenorDays = this.context.binding.get("value").get("tenorDays");

		if (!!this.context.options.paymentTerm.get("value")) {
			if (this.context.options.paymentTerm.get("value") == "004") {
				//-------------------------------------------------------------
				var multiTenorDates = bpmext.ui.getView("/DC_Templete1/4/Table1")?.getData();

				var maxDt = multiTenorDates.items[0].instalmentMaturityDate;
				var maxDtObj = new Date(maxDt);
				for (var i = 1; i < multiTenorDates.items.length; i++) {
					var dt = multiTenorDates.items[i].instalmentMaturityDate;
					var currenDtObj = new Date(dt);

					if (currenDtObj > maxDtObj) {
						maxDt = dt;
						maxDtObj = currenDtObj;
					}
				}

				var newMaturityDate = new Date(maxDt);
				newMaturityDate.setDate(maxDt.getDate());
				this.context.binding.get("value").set("maturityDate", newMaturityDate);
				var base = new Date(baseDate);
				var max = new Date(maxDtObj);
				base.setHours(0, 0, 0, 0);
				max.setHours(0, 0, 0, 0);
				if (base > max) {
					this.ui.get("baseDate").setValid(false, "Base Date must be <=  latest Maturity Date in the multi-tenor table");
				} else {
					this.ui.get("baseDate").setValid(true);
				}
				//--------------------------------------------------------------

				this.ui.get("transitDays").setEnabled(false);
				this.ui.get("transitDays").setData(0);
				this.ui.get("tenorDays").setEnabled(false);
				// this.ui.get("maturityDate").setEnabled(false);
				var newMat = new Date(newMaturityDate);
				var base = new Date(baseDate);
				newMat.setHours(0, 0, 0, 0);
				base.setHours(0, 0, 0, 0);
				var timeDifference = newMat - base;
				var totalDays = Math.floor(timeDifference / (1000 * 60 * 60 * 24));
				var tenorDays = totalDays;
			} else {
				this.ui.get("transitDays").setEnabled(true);
				this.ui.get("tenorDays").setEnabled(true);
				// this.ui.get("maturityDate").setEnabled(true);
				var mat = new Date(maturityDate);
				var base = new Date(baseDate);
				mat.setHours(0, 0, 0, 0);
				base.setHours(0, 0, 0, 0);
				var timeDifference = mat - base;
				var totalDays = Math.floor(timeDifference / (1000 * 60 * 60 * 24));
				var tenorDays = totalDays - transitDays;

				function addDaysToDate(date, days) {
					var result = new Date(date);

					result.setDate(result.getDate() + days);
					return result;
				}
				maturityDate = addDaysToDate(baseDate, tenorDays + transitDays);
				var validateDate = addDaysToDate(baseDate, 0);

				if (maturityDate < addDaysToDate(validateDate, transitDays)) this.ui.get("maturityDate").setValid(false, "Maturity Date Must be >= Base date plus tranist days");
				else this.ui.get("maturityDate").setValid(true);
			}
			this.context.binding.get("value").set("tenorDays", tenorDays);
			if (!!tenorDays && tenorDays < 0) this.ui.get("tenorDays").setValid(false, "Please enter a numeric number greater than  OR Equal zero");
			else if (!!transitDays && transitDays < 0) this.ui.get("transitDays").setValid(false, "Please enter a numeric number greater than  OR Equal zero");
			else {
				this.ui.get("transitDays").setValid(true);
				this.ui.get("tenorDays").setValid(true);
			}
		}
	}.bind(this);
	document.addEventListener("changeTenorTransit", (event) => {
		var parameter = event.detail;
		this.runCalculateTenorTransitDays(parameter);
	});
};
// this.calculateMaturityDate();
