// Utility Functions
function findFirstNonNullValue(array) {
	for (var i = 0; i < array.length; i++) {
		if (array[i] !== null && array[i] !== undefined) {
			return array[i];
		}
	}
	return null;
}

this.getViewByPath = function (path) {
	return bpmext.ui.getView(path) || null;
};

this.getFieldById = function (path) {
	return this.ui.get(path) || null;
};

function getDateOnly(date) {
	const d = new Date(date);
	return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

function getLatestDate(dates) {
	// Filter out invalid or null/undefined entries and parse valid dates
	const validDates = dates
		.map((date) => new Date(date)) // Convert each date to a Date object
		.filter((d) => !isNaN(d.getTime())); // Keep only valid Date objects

	if (validDates.length === 0) {
		return null; // No valid dates
	}

	// Get the maximum timestamp and convert it back to a Date object
	const latestDate = new Date(Math.max(...validDates.map((d) => d.getTime())));
	return latestDate;
}
